plot_df <- asv_master %>%
  
  mutate(
    
    RelativeAbundance = case_when(
      
      Category == "Water_only" ~ MeanRel_water,
      
      TRUE ~ MeanRel_skin
      
    ),
    
    Genus = ifelse(
      is.na(Genus) | Genus == "",
      "Unclassified",
      Genus
    )
    
  )

plot_df <- plot_df %>%
  mutate(
    Genus = as.character(Genus),
    Genus = str_trim(Genus),
    Genus = str_replace_all(Genus, "_", " "),
    Genus = ifelse(
      is.na(Genus) | Genus == "",
      "Unclassified",
      Genus
    )
  )

plot_df <- plot_df %>%
  
  filter(
    
    Genus!="Unclassified"
    
  )

plot_df <- plot_df %>%
  
  filter(
    
    Genus!="Uncultured"
    
