plot_spearman <- function(
    data,
    x,
    y,
    rho,
    pvalue,
    ylab){
  
  ggplot(
    data,
    aes_string(
      x=x,
      y=y
    )
  )+
    
    geom_point(
      alpha=.5,
      color="grey40",
      size=1.8
    )+
    
    geom_smooth(
      method="loess",
      color="#1F78B4",
      fill="#A6CEE3",
      linewidth=1
    )+
    
    annotate(
      
      "text",
      
      x=min(data[[x]],na.rm=TRUE),
      
      y=max(data[[y]],na.rm=TRUE),
      
      hjust=0,
      
      label=paste0(
        "\u03C1 = ",
        round(rho,3),
        "\nP < 0.001"
      ),
      
      fontface="bold",
      
      size=5
      
    )+
    
    labs(
      
      x="log10 Mean relative abundance",
      
      y=ylab
      
    )+
    
    theme_classic(base_size=14)
  
}

