hub_prop <- function(
    data,
    hub_col,
    module_col){
  
  data %>%
    
    group_by(
      .data[[module_col]]
    ) %>%
    
    summarise(
      
      Nodes=n(),
      
      Hubs=sum(
        .data[[hub_col]]
      ),
      
      PropHub=100*Hubs/Nodes
      
    ) %>%
    
    arrange(
      desc(PropHub)
    )
  
}

