get_role <- function(hub_degree, hub_btw){
  
  case_when(
    
    is.na(hub_degree) ~ NA_character_,
    
    hub_degree & hub_btw ~ "Both",
    
    hub_degree ~ "Degree",
    
    hub_btw ~ "BTW",
    
    TRUE ~ "None"
    
  )
  
}

alluvial_df <-
  
  persistent_ASVs %>%
  
  filter(
    Pattern == "LJA"
  ) %>%
  
  mutate(
    
    Larva_role = get_role(
      HubDegree_L,
      HubBTW_L
    ),
    
    Juvenile_role = get_role(
      HubDegree_J,
      HubBTW_J
    ),
    
    Adult_role = get_role(
      HubDegree_A,
      HubBTW_A
    )
    
  ) %>%
  
  select(
    
    Larva_ID,
    Post_ID,
    
    Larva_role,
    Juvenile_role,
    Adult_role
    
  )

alluvial_df <-
  
  alluvial_df %>%
  
  mutate(
    
    Trajectory = paste(
      Larva_role,
      Juvenile_role,
      Adult_role,
      sep = " → "
    )
    
  )

