make_cloud <- function(center_x,
                       center_y,
                       n,
                       radius_x,
                       radius_y){
  
  theta <- runif(n,0,2*pi)
  
  r <- sqrt(runif(n))
  
  data.frame(
    
    x = center_x + radius_x*r*cos(theta),
    
    y = center_y + radius_y*r*sin(theta),
    
    size = runif(
      n,
      2.4,
      4.2
    )
    
  )
  
}

