draw_network <- function(nodes,
                         edges,
                         persistent){
  
  list(
    
    geom_segment(
      data=edges,
      aes(x=x,
          y=y,
          xend=xend,
          yend=yend),
      linewidth=.45,
      colour="grey55"
    ),
    
    geom_point(
      
      data=nodes,
      
      aes(x,y,size=size),
      
      shape=21,
      
      fill="grey88",
      
      colour="grey35",
      
      stroke=.35
      
    ),
    
    geom_point(
      
      data=subset(nodes,persistent),
      
      aes(x,y),
      
      shape=21,
      
      size=4,
      
      fill="#D55E00",
      
      colour="black",
      
      stroke=1.3
      
    )
    
  )
  
}

############################################################
## Helper
############################################################

make_nodes <- function(x0,y0,coords){
  
  data.frame(
    
    id = seq_len(nrow(coords)),
    
    x = coords[,1] + x0,
    
    y = coords[,2] + y0
    
  )
  
}

