draw_network <- function(nodes,
                         edges){
  
  list(
    
    geom_segment(
      
      data=merge(
        edges,
        nodes,
        by.x="from",
        by.y="id"
      ) |>
        merge(
          nodes,
          by.x="to",
          by.y="id",
          suffixes=c("","2")
        ),
      
      aes(
        
        x=x,
        
        y=y,
        
        xend=x2,
        
        yend=y2
        
      ),
      
      linewidth=.45,
      
      colour="grey60"
      
    ),
    
    geom_point(
      
      data = nodes,
      
      aes(
        x,
        y,
        size = size
      ),
      
      shape = 21,
      
      fill = "grey90",
      
      colour = "grey55",
      
      stroke = .30
      
    ),
    
    geom_point(
      
      data = subset(nodes, Persistent),
      
      aes(
        x,
        y,
        size = size
      ),
      
      shape = 21,
      
      fill = "#D55E00",
      
      colour = "black",
      
      stroke = 1.0
      
    ),
    scale_size_identity()
  )
  
}

